  return <HaloAnnotationSurface preview={text}><form className="wb-editor wb-annotation" onSubmit={event=>{event.preventDefault();if(saving||client.getSnapshot().pending)return;setSaving(true);setNotice('');const old=saved.current,id=old?.id||makeId('annotation'),value={text,refs:[refValue]};submitted.current={id,version:old?draft.baseVersion+1:1,text};void client.command([old?{type:'expression.edit',id,expectedVersion:draft.baseVersion,title:'我的摘记',value}:{type:'expression.create',id,kind:'annotation',title:'我的摘记',value,author:'user'}],'annotation:'+refValue.id+':'+refValue.version).then(()=>{saved.current={id,version:old?draft.baseVersion+1:1};draft.committed(saved.current.version);setNoticeError(false);setNotice('摘记已保存');}).catch(error=>{setNoticeError(true);setNotice(error.message);}).finally(()=>setSaving(false));}}><label>我的摘记<HaloTextarea aria-label="我的摘记" value={text} onChange={e=>setText(e.target.value)} placeholder="写下摘记" rows={4}/></label><button className="wb-button" type="submit" disabled={saving||Boolean(client.getSnapshot().pending)}>保存摘记</button><FormFeedback client={client} owner={'annotation:'+refValue.id+':'+refValue.version} busy={saving} pendingLabel="正在保存摘记…" message={notice} error={noticeError} dirty={text!==(existing?.versions[existing.version].text||'')}/></form></HaloAnnotationSurface>;
