    {tab==='content'&&(selected.kind==='expression'&&entry.author==='user'&&entry.kind!=='ink'&&selected.version===entry.version?<ExpressionEditor key={entry.id} entry={entry} value={value} client={client}/>:<>{selected.version!==entry.version&&<p className="wb-muted">正在回看 v{selected.version}；当前为 v{entry.version}。旧版只读，不以旧稿覆盖当前。<button className="wb-button" onClick={onCurrent}>查看当前全文</button></p>}<Media entry={entry} value={value} client={client}/><h3 className="wb-material-title">{entry.title}</h3><MaterialText text={value.text||value.purpose||''} kind={entry.kind} fileName={value.origin?.fileName}/><p className="wb-muted">{entry.author==='agent'?'AI原稿，与用户表达分开保留':selected.kind==='expression'?'用户表达，历史正文只读':'原始材料，摘录与原件分别保留'}</p></>)}
