    {tab==='relations'&&<>{related.length?related.map(r=><RelationReview key={r.id} relation={r} client={client}/>):<HaloEmptyState kind="relations" icon="link" title="还没有明确的关系" description="空间同框和普通连线不会自动成为语义关系。可选中两条内容，写下关联依据。"><button className="wb-button" onClick={()=>setTab('content')}>返回材料内容</button></HaloEmptyState>}</>}
    {tab==='evolution'&&<EvolutionPanel concise key={entry.id} entries={entries}/>}
