  return <FeedbackProvider><TraceTooltipProvider><div className="wb-shell" data-workbench-ready={state.ready&&Boolean(host)}><aside className="wb-navigation"><a className="wb-wordmark" href="/app?view=canvas">Trace</a><nav aria-label="三大工作区">{([{id:'canvas',label:'思考画布',icon:'canvas'},{id:'capabilities',label:'能力库',icon:'library'},{id:'collaboration',label:'Agent 协作',icon:'work'}]as {id:View;label:string;icon:IconName}[]).map(item=><button key={item.id} aria-current={view===item.id?'page':undefined} onClick={()=>navigate(item.id)}><TraceIcon name={item.icon}/>{item.label}</button>)}</nav><div className="wb-recent"><span className="wb-kicker">最近画布</span><ItemList label="最近画布列表">{state.canvases.map(board=><button data-list-item key={board.id} className={state.canvas?.id===board.id?'is-current':''} onClick={()=>{void client.load(board.id).then(loaded=>{if(!loaded)return;writeLocal('resume:canvas',board.id);setSelection(readLocal('resume:selected:'+board.id,[]));setViewport(readLocal('resume:viewport:'+board.id,{x:0,y:0,k:1}));navigate('canvas');});}}><TraceIcon name="document"/>{board.title}</button>)}</ItemList>{host&&<button onClick={()=>{void client.createCanvas().then(id=>{writeLocal('resume:canvas',id);setSelection([]);setViewport({x:0,y:0,k:1});navigate('canvas');}).catch(fail);}}><TraceIcon name="plus"/>新建画布</button>}</div><footer><button onClick={()=>setOverlay('search')}><TraceIcon name="search"/>搜索</button><button onClick={()=>setOverlay('settings')}><TraceIcon name="settings"/>设置</button><div className="wb-person"><span>{host?.preferences?.displayName?.slice(0,1)||'我'}</span><span>{host?.preferences?.displayName||'个人空间'}</span></div></footer></aside>
  <header className="wb-topbar"><button className="wb-icon-button wb-mobile-workspaces" aria-label="切换工作区" onClick={()=>setOverlay('navigation')}><TraceIcon name="canvas"/></button><div className="wb-breadcrumb">个人空间 <span>/</span> <strong>{view==='canvas'?state.canvas?.title||'思考画布':view==='capabilities'?'能力库':'Agent 协作'}</strong><TraceIcon name="down" size={16}/></div>{searchReturnKey&&<button className="wb-icon-button" aria-label="返回搜索结果" title="返回搜索结果" onClick={()=>setOverlay('search')}><TraceIcon name="back"/></button>}<GooeySearch onSearch={text=>{setQuery(text);setSearchReturnKey(null);searchScroll.current=0;setOverlay('search');}}/><TraceMenu label="工作台更多操作" actions={[...((window as any).traceNative?[{id:'legacy',label:'打开旧版内容（独立保留）',icon:'library' as const}]:[]),{id:'recovery',label:'导出当前恢复内容',icon:'document'},{id:'reload',label:'重新读取已保存内容',icon:'history'}]} onAction={id=>id==='legacy'?void (window as any).traceNative.requestCapability({operation:'workbench.legacy.open'}):id==='recovery'?downloadJson('Trace-recovery.json',{product:client.getSnapshot().host,canvas:client.getSnapshot().canvas,pending:state.pending,limits:'原件二进制不在此JSON中；这不是完整工作区备份或能力分享包。'}):void client.reloadAfterConflict()}/></header>
  <main className={'wb-main wb-main-'+view}>
    {state.readError&&state.ready&&<div className="wb-read-notice"><TraceStatusNotice phase="error" title="读取未完成，当前工作面已保留" description={state.readError+' 当前显示上次成功读取的内容；选区和本地草稿仍在，不代表已经同步最新版本。'} actions={<button className="wb-button" onClick={()=>{void client.load();}}>重试读取，不丢当前草稿</button>}/></div>}
    {!state.ready?<section className="wb-onboarding"><ProcessState phase={(state.readError||state.error)?'error':'pending'}>{state.readError||state.error||'正在读取工作区…'}</ProcessState><button className="wb-button" onClick={()=>{void client.load();}}>重新读取</button></section>:!host?<section className="wb-onboarding"><TraceIcon name="canvas" size={20}/><h1>{state.legacy?'准备接续已有内容':'从一点想法开始'}</h1><p>{state.legacy?'现有原话、来源、理解版本和草稿不会被当成空白。迁移目前只在测试副本验证；完整旧动作适配通过前，不对个人库开放转换。可以先导出快照或回原工作区。':'留下材料，记录想法。'}</p>{state.legacy&&<button className="wb-button" onClick={()=>downloadJson('Trace-before-content-v2.json',{revision:state.revision,host:state.legacy})}>先导出转换前快照</button>}<LiquidButton className="wb-button wb-primary" onClick={()=>{if(state.legacy){location.href='/app?view=home';return;}void client.prepare().catch(fail);}}>{state.legacy?'回到现有工作区':'开始画布'}</LiquidButton></section>:<>
      {view==='canvas'&&state.canvas&&<div className="wb-canvas-layout"><CanvasSurface document={state.canvas} host={host} selected={selected} setSelected={setSelection} viewport={viewport} setViewport={value=>{setViewport(value);writeLocal('resume:viewport:'+state.canvas!.id,value);}} onLayout={(scene,action,revision)=>client.layout(scene,action,undefined,revision)} onCreate={create} onFiles={(list,position)=>{void files(list,position);}} onDiscuss={()=>{void discuss();}} onActivation={()=>setOverlay('activation')} onCapture={position=>openCapture(undefined,position)} onInspect={()=>setInspector(true)} renderNode={node=><Card node={node} host={host} client={client} onInspect={()=>{setSelection([node.id]);setInspector(true);}}/>} onDetachRelation={(id,expectedVersion)=>client.command([{type:'relation.decide',id,expectedVersion,decision:'detached'}])}/>{inspector&&currentRef&&<Inspector key={currentRef.kind+currentRef.id} selected={currentRef} onCurrent={()=>{setDirect({kind:currentRef.kind,id:currentRef.id,version:null});setSelected([]);}} host={host} client={client} tab={tab} setTab={setTab} onCapture={source=>openCapture(source)} onClose={()=>{setInspector(false);requestAnimationFrame(()=>{const n=selected[0];(n?document.querySelector<HTMLElement>('[data-node-id="'+CSS.escape(n)+'"]'):document.querySelector<HTMLElement>('.wb-ic-viewport'))?.focus();});}} onDiscuss={()=>{void discuss([currentRef]);}} onCapability={()=>{void formCapability(currentRef).catch(fail);}} onPacket={(resourceId,source)=>setSharing({resourceId,source})}/>}</div>}
      {view==='capabilities'&&<div className="wb-library-layout"><CollectionPanel title="能力" caption="能力库" current={activeCapability&&host.capabilities[activeCapability]?.title||"选择或新建能力"} count={visibleCapabilities.length} createLabel="新建能力" onCreate={createCapability}><div className="wb-page-heading"><div><h1>能力库</h1></div><button className="wb-icon-button" data-collection-close aria-label="新建能力" onClick={createCapability}><TraceIcon name="plus"/></button></div><div className="wb-library-entry-actions"><button className="wb-button" onClick={()=>setSharing({})}>接收版本包</button><button className="wb-button" onClick={()=>setFeedback({unresolved:true})}>待核对反馈</button><label>分类<HaloSelect aria-label="能力库分类" value={libraryGroup} onValueChange={value=>setLibraryGroup(value)}><option value="all">全部</option><option value="method">方法</option><option value="template">提示模板</option><option value="instruction">AI 指令</option></HaloSelect></label><TemplateLibrary client={client} actionLabel="打开库中条目" onInsert={(entry)=>selectCapability(entry.id)}/></div><ItemList label="能力列表">{visibleCapabilities.map(entry=><CapabilitySummary key={entry.id} entry={entry} active={activeCapability===entry.id} onSelect={()=>selectCapability(entry.id)}/>)}</ItemList>{!visibleCapabilities.length&&<HaloEmptyState compact kind="capability-list" icon="library" title={Object.keys(host.capabilities).length?"此分类暂无能力":"还没有保存的方法"} description={Object.keys(host.capabilities).length?"其他分类的条目仍保留，切换筛选即可找回。":"可以在右侧保存自己的方法，或先浏览模板库。"}>{Object.keys(host.capabilities).length>0&&<button className="wb-button" onClick={()=>setLibraryGroup('all')}>显示全部能力</button>}</HaloEmptyState>}</CollectionPanel>{activeCapability&&host.capabilities[activeCapability]?<CapabilityHistory key={activeCapability} entry={host.capabilities[activeCapability]} version={capabilityVersion} onVersion={setCapabilityVersion} onUseVersion={ref=>{void discuss([ref]);}} onShareVersion={ref=>setSharing({ref})} onOpenSource={openRef} sourceTitle={ref=>content(host,ref)?.entry.title||'来源暂不可用'} onOpenFeedback={(id,version)=>setFeedback({id,version})} feedback={<FeedbackPanel client={client} target={{kind:'capability',id:activeCapability,version:capabilityVersion||host.capabilities[activeCapability].version}} onOpen={setFeedback}/>}><CapabilityEditor key={activeCapability} entry={host.capabilities[activeCapability]} client={client} onTrial={entry=>{void client.command([{type:'capability.state',id:entry.id,expectedVersion:entry.version,state:'trial',reason:'准备一次限定范围的试用'}]).then(()=>discuss([{kind:'capability',id:entry.id,version:entry.version}])).catch(fail);}}/></CapabilityHistory>:<div className="wb-empty-pane"><HaloEmptyState kind="capability-selection" icon="library" title={Object.keys(host.capabilities).length?"选择一项能力":"把方法沉淀到能力库"} description="打开已有条目查看完整版本，或保存自己的方法。模板插入与发布都需要明确确认。"><button className="wb-button wb-primary" onClick={createCapability}><TraceIcon name="plus"/>{Object.keys(host.capabilities).length?"另建一项能力":"新建第一项能力"}</button><TemplateLibrary client={client} label="浏览模板库" actionLabel="打开库中条目" onInsert={entry=>selectCapability(entry.id)}/></HaloEmptyState></div>}</div>}
      {view==='collaboration'&&<div className="wb-collaboration"><CollectionPanel title="协作记录" caption={collabTab==='external'?"外部任务":"共同思考"} current={collabTab==='external'?(taskPreparing?"正在准备任务":activeTask&&host.tasks[activeTask]?.title||"选择一个任务"):(activeThinking&&host.sessions[activeThinking]?.title||"选择一段思考")} count={collabTab==='internal'?Object.keys(host.sessions).length:Object.keys(host.tasks).length} createLabel={collabTab==='internal'?"新建共同思考":"准备外部任务"} onCreate={()=>collabTab==='internal'?void discuss():prepareTask()}><div className="wb-page-heading"><div><h1>Agent 协作</h1></div><button className="wb-icon-button" data-collection-close aria-label={collabTab==='internal'?"新建共同思考":"准备外部任务"} onClick={()=>collabTab==='internal'?void discuss():prepareTask()}><TraceIcon name="plus"/></button></div><HaloSegmented label="协作记录类型" value={collabTab} onValueChange={value=>{setCollabTab(value as 'internal'|'external');if(value==='external')setTaskPreparing(!activeTask);}} items={[{value:'internal',label:'Trace 内思考',count:Object.keys(host.sessions).length},{value:'external',label:'外部任务',count:Object.keys(host.tasks).length}]}/><RecordBrowser key={collabTab} records={collabTab==='internal'?Object.values(host.sessions):Object.values(host.tasks)} kind={collabTab==='internal'?'thinking':'task'} activeId={collabTab==='internal'?activeThinking:activeTask} initial={()=>readLocal<RecordBrowseState>('browse:records:'+collabTab,defaultRecordBrowse)} remember={next=>writeLocal('browse:records:'+collabTab,next)} onSelect={id=>{setSearchDestination(null);if(collabTab==='internal')setActiveThinking(id);else{setActiveTask(id);setTaskPreparing(false);}}} renderStatus={record=>'messages'in record?`${record.messages.length} 段已保存`:<AgentTaskBadge task={record} runs={executions.runs} ready={executions.ready} error={executions.error}/>}/>{collabTab==='external'&&!Object.keys(host.tasks).length&&<HaloEmptyState compact kind="task-list" icon="work" title="还没有外部任务" description="先保存目标、步骤和明确范围；保存准备不会启动执行。"><button className="wb-button" data-collection-close onClick={prepareTask}>填写任务目标</button></HaloEmptyState>}</CollectionPanel><section className="wb-thinking-pane">{collabTab==='internal'?(activeThinking&&host.sessions[activeThinking]?<><div className="wb-page-heading wb-search-destination" tabIndex={-1} data-search-destination={'thinking:'+activeThinking}><h2>{host.sessions[activeThinking].title}</h2><HaloBadge>明确提交后由本机 AI 回应</HaloBadge></div><section className="wb-reference-summary"><HaloBadge>讨论起始引用 {host.sessions[activeThinking].refs.length} 项（不随后续草稿改变）</HaloBadge>{host.sessions[activeThinking].refs.map(ref=><button key={ref.kind+ref.id+ref.version} className="wb-reference" onClick={()=>setReferenceView(ref)}><TraceIcon name="document"/>{content(host,ref)?.entry.title||ref.id}<small>v{ref.version}</small></button>)}</section><DiscussionBrowser key={activeThinking} session={host.sessions[activeThinking]} destination={searchDestination} onDestinationHandled={()=>setSearchDestination(null)} initial={readLocal<ReadingPosition|null>('browse:thinking:'+activeThinking,null)||undefined} remember={next=>writeLocal('browse:thinking:'+activeThinking,next)} onContinue={messageId=>setThinkingContinuation({sessionId:activeThinking,messageId,requestId:makeId('continue')})} empty={<HaloEmptyState compact kind="message" icon="pencil" title="把第一段想法留下来" description="在下方输入并保存。这只是用户讨论记录，不会自动请 AI 回应。"><button className="wb-button" onClick={()=>document.querySelector<HTMLTextAreaElement>('.wb-thinking-composer textarea')?.focus()}>开始写想法</button></HaloEmptyState>} renderMessage={(m,_index,readingQuery)=><><p><HistoryText text={m.text} query={readingQuery}/></p><ReferenceScopeSnapshot client={client} scope={m.scope} messages={host.sessions[activeThinking].messages}/>{m.template&&<small>最后插入模板：{host.capabilities[m.template.id]?.versions[m.template.version]?.title||m.template.id} · v{m.template.version}</small>}<InstructionSnapshot client={client} refs={m.instructions||[]}/><button className="wb-button" onClick={()=>setMessageWriteback({sessionId:activeThinking,messageId:m.id})}><TraceIcon name="copy"/>从这段原话留下线索</button><button className="wb-button" onClick={()=>setFeedback({seed:{context:{kind:'thinking',id:activeThinking,messageId:m.id}}})}>记录这段思考的版本反馈</button></>}><SessionComposer key={activeThinking} session={host.sessions[activeThinking]} client={client} continuation={thinkingContinuation?.sessionId===activeThinking?thinkingContinuation:null} onContinuationConsumed={()=>setThinkingContinuation(null)}/><ThinkingExecution onOpenWriteback={openRef} onPlaceWriteback={placeWriteback} key={activeThinking+'-ai'} session={host.sessions[activeThinking]} client={client} executions={executions} onFeedbackResult={feedbackResult} onContinue={messageId=>setThinkingContinuation({sessionId:activeThinking,messageId,requestId:makeId('continue')})}/></DiscussionBrowser></>:<HaloEmptyState kind="discussion" icon="discussion" title="还没有讨论记录" description="先留下问题或想法。保存讨论不等于运行模型，只有明确提交后才会执行。"><button className="wb-button wb-primary" onClick={()=>{void discuss();}}><TraceIcon name="plus"/>开始一段共同思考</button></HaloEmptyState>):<><HaloDisclosure className="wb-task-preparer" title="准备一个任务" open={taskPreparing} onOpenChange={setTaskPreparing}><p className="wb-halo-hint">这里是独立草稿。保存会留下新的任务准备，不会改写已保存的任务。</p><TaskPreparation client={client} refs={scope()} isOpen={taskPreparing} onSaved={setActiveTask} onViewSaved={id=>{setActiveTask(id);setTaskPreparing(false);}}/></HaloDisclosure>{activeTask&&host.tasks[activeTask]&&<HaloSurface className="wb-task-detail"><h3 className="wb-search-destination" tabIndex={-1} data-search-destination={'task:'+activeTask}>{host.tasks[activeTask].title}</h3><AgentTaskBadge task={host.tasks[activeTask]} runs={executions.runs} ready={executions.ready} error={executions.error}/><p className="wb-halo-hint">{executions.runs.some(r=>r.taskId===activeTask)?"本次执行与返回结果见下方。":"核对这次准备后，可在下方提交执行。"}</p><section className="wb-task-context" aria-label="本次任务引用"><h4>本次引用 {host.tasks[activeTask].refs.length} 项</h4>{host.tasks[activeTask].refs.length?host.tasks[activeTask].refs.map(ref=><button key={ref.kind+ref.id+ref.version} className="wb-reference" disabled={!content(host,ref)} onClick={()=>setReferenceView(ref)}><TraceIcon name="document"/><span>{content(host,ref)?.entry.title||"引用内容暂不可用"}</span><small>v{ref.version}</small></button>):<p className="wb-halo-hint">未带入画布材料；发送范围以已保存的目标、步骤与 AI 指令为准。</p>}</section><SavedTaskPlan client={client} instructions={host.tasks[activeTask].instructions} plan={host.tasks[activeTask].plan}/><button className="wb-button" onClick={()=>setFeedback({seed:{context:{kind:'task',id:activeTask}}})}>记录这次准备的版本反馈</button><TaskExecution onOpenWriteback={openRef} onPlaceWriteback={placeWriteback} key={activeTask} task={host.tasks[activeTask]} client={client} executions={executions} onFeedbackResult={feedbackResult} onCancelPreparation={()=>{void client.command([{type:'task.cancel',id:activeTask}]).catch(fail);}}/><HaloDisclosure className="wb-existing-execution" open={Boolean(host.tasks[activeTask].execution)} title="关联已有运行回执（独立范围）"><ExecutionView key={activeTask} client={client} task={host.tasks[activeTask]}/></HaloDisclosure></HaloSurface>}</>}</section></div>}
    </>}
    <GlobalFeedback client={client} notice={notice} onDismiss={()=>setNotice('')}/>
  </main><div className="wb-save-status" aria-label="工作区保存状态">{state.saving?'正在保存…':state.pending?'保存尚未确认':state.loading?'正在读取，当前内容保留…':state.readError?'读取未完成，当前内容保留':state.host?'已保存内容':'尚未开始'}{state.host&&<span className="wb-storage-location" title={`内容版本 ${state.revision}；画布版本 ${state.canvas?.revision||0}`}>{namespace==='demo'?'演示空间':(window as any).traceNative?'本机':'此浏览器'}</span>}</div>
  {overlay==='navigation'&&<WorkbenchModal title="切换工作区" onClose={()=>setOverlay(null)}><div className="wb-editor">{(['canvas','capabilities','collaboration']as View[]).map((v,i)=><button className="wb-button" key={v} onClick={()=>{navigate(v);setOverlay(null);}}>{['思考画布','能力库','Agent 协作'][i]}</button>)}<section aria-label="最近画布" className="wb-editor"><span className="wb-kicker">最近画布</span>{state.canvases.map(board=><button className="wb-button" key={board.id} onClick={()=>{void client.load(board.id).then(loaded=>{if(!loaded)return;writeLocal('resume:canvas',board.id);setSelection(readLocal('resume:selected:'+board.id,[]));setViewport(readLocal('resume:viewport:'+board.id,{x:0,y:0,k:1}));navigate('canvas');setOverlay(null);});}}>{board.title}</button>)}{host&&<button className="wb-button" onClick={()=>{void client.createCanvas().then(id=>{writeLocal('resume:canvas',id);setSelection([]);setViewport({x:0,y:0,k:1});navigate('canvas');setOverlay(null);}).catch(fail);}}>新建画布</button>}</section><button className="wb-button" onClick={()=>setOverlay('search')}>搜索内容</button><button className="wb-button" onClick={()=>setOverlay('settings')}>个人与设置</button></div></WorkbenchModal>}
  {imports.panel}
  {overlay==='settings'&&<WorkbenchModal title="个人与显示设置" onClose={()=>setOverlay(null)}><PreferencesEditor client={client} host={host} onSaved={()=>setOverlay(null)}><label>外观<HaloSelect aria-label="外观" value={appearance} onValueChange={value=>setAppearance(value as 'system'|'light'|'dark')}><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></HaloSelect></label></PreferencesEditor></WorkbenchModal>}
  {(overlay==='search'||overlay==='activation')&&<WorkbenchModal title={overlay==='search'?'找回内容':'激活旧线索'} onClose={()=>setOverlay(null)}>{host?<WorkspaceSearch key={overlay} client={client} host={host} query={query} onQuery={setQuery} options={searchOptions} onOptions={setSearchOptions} returnKey={searchReturnKey} scrollState={searchScroll} loading={state.loading} readError={state.readError} activation={overlay==='activation'} onReturnCanvas={()=>{setOverlay(null);navigate('canvas');}} onOpen={openSearchHit} onPlace={async(hit,owner,isCurrent)=>{if(hit.target.type!=='content')return;const ref=hit.target.ref,target=client.getSnapshot().canvas;await insert(ref,{x:160,y:160},200,target,hit.version!==hit.currentVersion,owner,isCurrent);if(isCurrent()&&client.getSnapshot().canvas?.id===target?.id){setSearchReturnKey(hit.key);navigate('canvas');setOverlay(null);}else setNotice('内容已放到原目标画布，当前页面未切换。');}}/>:<p>先打开已有工作区，再查找保存的内容；未将旧库当成空白。</p>}</WorkbenchModal>}

  {messageWriteback&&<MessageWriteback key={messageWriteback.sessionId+':'+messageWriteback.messageId} client={client} {...messageWriteback} onClose={()=>setMessageWriteback(null)} onOpen={ref=>{setMessageWriteback(null);openRef(ref);}} onPlace={placeWriteback}/>}
  {referenceView&&<ReferenceViewer client={client} reference={referenceView} onClose={()=>setReferenceView(null)}/>}
  {feedback&&host&&<CapabilityFeedbackDialog key={JSON.stringify(feedback)} client={client} open={feedback} executions={executions} onReturnSearch={feedback.id&&searchReturnKey?.startsWith('feedback:'+feedback.id+':')?()=>{setFeedback(null);setOverlay('search');}:undefined} onClose={()=>setFeedback(null)}/>}
  {sharing&&<CapabilitySharing client={client} exportRef={sharing.ref} initialResourceId={sharing.resourceId} focusSource={sharing.source} viewOnly={Boolean(sharing.resourceId)} onClose={()=>setSharing(null)} onSelect={id=>{selectCapability(id);navigate('capabilities');}}/>}
  {captureRecovery&&<MaterialDraftRecovery raw={captureRecovery.raw} onClose={()=>setCaptureRecovery(null)} onExport={()=>downloadJson('Trace-material-draft-recovery.json',{scope:'Only this explicitly requested local capture draft; not a workspace backup or capability package',storageKey:captureRecovery.sourceKey,raw:captureRecovery.raw})} onRestart={()=>{const recovery=captureRecovery;try{localStorage.setItem('trace-workbench:'+namespace+':'+recovery.sourceKey,JSON.stringify(newCaptureDraft(recovery.source)));}catch{fail(Error('无法保存新草稿，原记录未被覆盖。'));return;}setCaptureRecovery(null);openCapture(recovery.source,recovery.position);}}/>}
  {capture&&<MaterialCapture key={capture.draft.id} source={capture.source} draft={capture.draft} client={client} saved={Boolean(host?.materials[capture.draft.id])} pending={Boolean(state.pending)} onChange={draft=>{writeLocal('material-capture:'+(capture.source?.entry.id||'new'),draft);setCapture(current=>current?.draft.id===draft.id?{...current,draft}:current);}} onSave={saveCapture} onClose={()=>setCapture(null)}/>}
  </div></TraceTooltipProvider></FeedbackProvider>;
